  'ops1.refusal.computedNet': 'આ પાના પર કોઈ સરવાળો-બાદબાકી થતી નથી: કુલ, કપાત અને ચોખ્ખું દરેક બિલ માટે સર્વરના આંકડા છે.',
  'ops1.refusal.pageCount': 'પાનાંની ગણતરી બતાવાતી નથી: સર્વર આ યાદીનાં બિલ ગણતું નથી.',
  'ops1.refusal.smsDelivery': 'આ પાનું કહી શકતું નથી કે પૂર્વદર્શન સંદેશ કોને મળ્યો; તે સંદેશ પહોંચ્યાની માહિતી વાંચતું નથી.',
  'ops1.refusal.earlyClose': 'અહીં કોઈ સભ્ય પોતાનો વાંધાનો સમય વહેલો બંધ કરી શકતી નથી, અને બીજા દિવસની કોઈ ચુકવણી થતી નથી.',
  'ops1.refusal.holes': 'દરેક બિલની ચુકવણી અલગથી થાય છે; અધૂરું બિલ બીજાંને રોકતું નથી, અને કોઈ યાદી દરેક બિલની રાહ જોતી નથી.',
  'ops1.refusal.crossOrg': 'મંજૂરી બે સંસ્થાઓ વચ્ચે જતી નથી: તે આ જ સંસ્થાના પોતાના ડેરી ડેસ્ક પાસે રહે છે.',
  'ops1.refusal.namesKept': 'અહીં કોઈ વચન નથી કે નામ કેટલો સમય યાદી પર રહેશે.',
  'ops1.refusal.disputedMask': 'આ પાનું કોઈ પણ સ્થિતિમાં કોઈ સભ્યનું નામ બતાવતું નથી; તે સભ્ય કોડ બતાવે છે.',
  'ops1.refusal.requestRelease': 'અહીં રિલીઝની વિનંતી અસ્તિત્વમાં નથી: જમાકર્તાની કોઈ વિનંતી આ કન્સોલ સુધી પહોંચતી નથી, અને આ પાનેથી કંઈ રિલીઝ થતું નથી.',
  'ops1.refusal.partial': 'અહીં બુકિંગનો કોઈ ભાગ ક્યારેય રિલીઝ થતો નથી: આખી બુકિંગ રિલીઝ થાય છે અથવા બિલકુલ નહીં, અને આ પાના પર કંઈ બાદ થતું નથી.',
  'ops1.refusal.lenderNoc': 'કોઈ ધિરાણકર્તાની વાંધો-નથી મંજૂરી માગવામાં આવતી નથી, કારણ કે આ પ્લેટફોર્મ પર હજી કોઈ રસીદ ગીરવે નથી.',
  'ops1.refusal.outWeigh': 'આ પ્લેટફોર્મ પર રિલીઝ વખતે બહાર જતા વજનની રસીદ સાથે તપાસ થતી નથી.',
  'ops1.refusal.depositorOnly': 'અહીં કોઈ નિયમ કહેતો નથી કે રિલીઝ કોણ માગી શકે, કારણ કે હજી કોઈ વિનંતી થઈ શકતી નથી.',
  'ops1.refusal.receiptBalance': 'અહીં રસીદ પર કોઈ બાકી જથ્થો નથી; આ પાના પર કંઈ ઘટાડીને ગણાતું નથી.',
  'ops1.refusal.releasePromise': 'આ પાનું અસ્તિત્વમાં ન હોય તેવી વિનંતી વિશે કોઈ વચન આપતું નથી; રિલીઝ અટકેલી છે, ઉપર કહ્યા પ્રમાણે.',
  'ops1.refusal.zeroSum': 'કંઈ થયું નથી, તેથી કંઈ મેળવાયું, પતાવાયું કે ખસેડાયું નથી.',
  'ops1.refusal.onCall': 'આ પાનાંમાંથી કોઈને બોલાવાતું કે જાણ કરાતી નથી.',
  'ops1.refusal.auditTrail': 'કોઈ ઑડિટ નોંધ લખાતી નથી, કારણ કે કોઈ કાર્ય થયું નથી.',
  'ops1.withdrawal.title': 'ગોદામમાંથી રિલીઝ (ઉપાડ)',
  'ops1.withdrawal.lead': 'આ પ્લેટફોર્મ પર સંગ્રહેલો માલ ગોદામમાંથી કેવી રીતે નીકળે છે. આ પાનું કંઈ વાંચતું નથી અને કંઈ બદલતું નથી.',
  'ops1.withdrawal.statementTitle': 'અહીં રિલીઝ કેવી રીતે થાય છે',
  'ops1.withdrawal.statement': 'રિલીઝ આખી બુકિંગની થાય છે, અને ગોદામ સંચાલક કરે છે. સંગ્રહ ફી રિલીઝ વખતે જમાકર્તાના વૉલેટમાંથી લેવાય છે. જમાકર્તા પોતાના સાઇન-ઇનમાં રિલીઝ અને તેની ફી જાતે પાકી ન કરી શકે ત્યાં સુધી રિલીઝ અટકેલી છે.',
  'ops1.withdrawal.noPartial': 'બુકિંગ આખી રિલીઝ થાય છે; તેના કોઈ ભાગની રિલીઝ થતી નથી.',
  'ops1.withdrawal.noPledge': 'આ પ્લેટફોર્મ પર હજી કોઈ રસીદ ગીરવે નથી.',
  'ops1.withdrawal.paused': 'રિલીઝ અટકેલી છે: સંગ્રહ ફી જમાકર્તાએ પાકી કર્યા વગર તેના વૉલેટમાંથી નીકળી જાત. તે જાતે પાકી ન કરી શકે ત્યાં સુધી આ કન્સોલમાંથી કંઈ રિલીઝ થઈ શકતું નથી.',
  'ops1.withdrawal.howLink': 'રિલીઝ કેવી રીતે થાય છે',
