  'ops1.chain.payoutAct.success.title': 'કંઈ કરવામાં આવ્યું નથી',
  'ops1.chain.payoutAct.success.body': 'કોઈ બિલ મોકલાયું, મંજૂર થયું કે ચૂકવાયું નથી.',
