  'ops1.aeps.none': 'કંઈ નહીં',
  'ops1.aeps.home.title': 'AePS: સંચાલકનો લૉગ',
  'ops1.aeps.home.lead': 'જ્યારે ગ્રાહક આ ડેસ્ક પર બેંકનું ફિંગરપ્રિન્ટ ઉપકરણ વાપરે છે, ત્યારે પૈસા બેંક પોતાની સિસ્ટમમાં મોકલે છે. આ કન્સોલ ફક્ત સંચાલકનો રેકોર્ડ રાખે છે કે બેંકના ઉપકરણે શું બતાવ્યું, તેથી વધુ કંઈ નહીં.',
  'ops1.aeps.home.kept': 'એક રેકોર્ડમાં સેવા, બેંકનું નામ, ખાતાના છેલ્લા ચાર અંક, બેંકના ઉપકરણ પર દેખાયેલી રકમ અને બાકી, પરિણામ, શું ખોટું થયું અને પ્રયાસ નંબર રહે છે. તેમાં આધારનો કોઈ અંક રહેતો નથી અને તે આ પ્લેટફોર્મ પર કોઈના ખાતા સાથે જોડાતો નથી.',
  'ops1.aeps.home.attempts': 'ફિંગરપ્રિન્ટ વધુમાં વધુ ત્રણ વાર અજમાવી શકાય. ત્રીજી નિષ્ફળતા પછી ગ્રાહકને બેંક શાખા કે બેંક મિત્ર પાસે મોકલો અને નોંધમાં લખો કે ક્યાં મોકલ્યા.',
  'ops1.aeps.home.enabled': 'ફક્ત એ જ સક્રિય એમ્બેસેડર ઘટના નોંધી શકે છે જેની પ્રોફાઇલ AePS માટે ચાલુ છે; બીજા કોઈને પ્રયાસ કરતાં આ જ કહેવામાં આવે છે.',
  'ops1.aeps.home.recordLink': 'ઘટના નોંધો',
