  'ops1.aeps.record.lead': 'ગ્રાહકે ઉપયોગ કર્યા પછી, બેંકના ઉપકરણે જે બતાવ્યું તેના પરથી આ ભરો. નોંધવાથી કંઈ મોકલાતું નથી.',
