  'ops1.aeps.record.deviceHint': 'જો તમે જાણતા હો તો જ આ ટિક કરો: આ પ્લેટફોર્મ કોઈ ઉપકરણ ચકાસી શકતું નથી, તેથી ટિક તમારો શબ્દ છે. જો તે પ્રમાણિત ન હોય, તો તેને ખાલી રાખો અને અટકાવેલી ઘટના નોંધો.',
  'ops1.aeps.record.status': 'પરિણામ',
  'ops1.aeps.record.exception': 'શું ખોટું થયું',
