  'ops1.aeps.record.attemptHint': 'ફિંગરપ્રિન્ટ વધુમાં વધુ {max} વાર અજમાવી શકાય. ત્રીજી નિષ્ફળતા પછી ગ્રાહકને બેંક શાખા કે બેંક મિત્ર પાસે મોકલો અને નોંધમાં લખો કે ક્યાં.',
