  'ops1.aeps.reason.notEnabled': 'તમારી પ્રોફાઇલ AePS ઘટનાઓ નોંધવા માટે ચાલુ નથી. ફક્ત AePS ચાલુ હોય તેવા સક્રિય એમ્બેસેડર જ તે નોંધી શકે છે; તમારા સુપરવાઇઝરને પૂછો.',
  'ops1.aeps.reason.off': 'આ સંસ્થા માટે એમ્બેસેડર મોડ્યુલ બંધ છે, તેથી કોઈ ઘટના નોંધી શકાતી નથી.',
  'ops1.aeps.reason.q7aAadhaar': 'સર્વરે તે નકાર્યું કારણ કે તેમાં આધારનું ક્ષેત્ર હતું. આ પ્લેટફોર્મ પર આધારના અંક નોંધાતા નથી.',
  'ops1.aeps.reason.q7aCustomer': 'સર્વરે તે નકાર્યું કારણ કે તેમાં ગ્રાહકનું ખાતું દર્શાવ્યું હતું. AePS રેકોર્ડ આ પ્લેટફોર્મ પર કોઈના ખાતા સાથે જોડાતો નથી.',
  'ops1.aeps.reason.rule': 'સર્વરે આ જોડાણ નકાર્યું. પરિણામ, શું ખોટું થયું અને પ્રયાસ નંબર તપાસો.',
