  'ops1.aeps.reason.ev_exception': 'યાદીમાંથી પસંદ કરો કે શું ખોટું થયું.',
  'ops1.aeps.reason.ev_amountMissing': 'ઉપાડમાં એ રકમ હોવી જોઈએ જે બેંકના ઉપકરણ પર દેખાઈ.',
  'ops1.aeps.reason.ev_amountNotAllowed': 'ફક્ત ઉપાડમાં રકમ હોય છે: બાકી પૂછપરછ કે મિની સ્ટેટમેન્ટ માટે તે ખાલી કરો.',
  'ops1.aeps.reason.ev_amount': 'રકમ અંકમાં લખો, જેમ કે 2000 કે 2000.50.',
