  'ops1.kiosk.home.tierNone': 'તમારી પ્રોફાઇલ પર કોઈ શ્રેણી નક્કી નથી.',
  'ops1.kiosk.home.twoFacts': 'કિયોસ્ક મોડ અને તાલીમ બે અલગ હકીકતો છે, અને એક નોંધવાથી બીજી બદલાતી નથી. એમ્બેસેડર તરીકે ખેડૂતને જોડવા, કે તેના માટે લિસ્ટિંગ કરવા બંને જોઈએ. તમારી સંસ્થાના એમ્બેસેડર મેનેજર દરેક નક્કી કરે છે.',
