  'ops1.kiosk.home.stepsTitle': 'પગલાં',
  'ops1.kiosk.home.stepsLead': 'આ ડેસ્ક પર ફક્ત પહેલું પગલું થાય છે. બાકીનું દરેક પગલું કહે છે કે તે પોતાના સાઇન-ઇનમાં શું કરે છે, અને ડેસ્ક કેમ નથી કરતું.',
