  'ops1.kiosk.state.off': 'તમારી સંસ્થા માટે એમ્બેસેડર કાર્યક્રમ બંધ છે.',
  'ops1.kiosk.state.error': 'હમણાં તમારી પ્રોફાઇલ વાંચી શકાઈ નથી.',
  'ops1.kiosk.start.title': 'નવા નંબર માટે ખાતું બનાવો',
  'ops1.kiosk.start.lead': 'તેનો ફોન નંબર, નામ અને ભાષા લખો. નંબર નવો હોય તો ખાતું બને છે. નંબરનું ખાતું પહેલેથી હોય તો કંઈ બનતું નથી અને એ ખાતા વિશે કંઈ બતાવાતું નથી.',
