  'ops1.chain.kioskAct.success.title': 'આ નંબરનું ખાતું છે; તે પોતાના ફોન પર સાઇન ઇન કરે છે',
  'ops1.chain.kioskAct.success.body': 'અહીં બીજું કંઈ કરાયું નથી. સારાંશમાં જે લખ્યું છે તે તેને કહો.',
