  'ops1.kiosk.reason.exists': 'આ નંબરનું ખાતું પહેલેથી છે. તે જાતે, પોતાના ફોન પર, સાઇન ઇન કરે છે.',
  'ops1.kiosk.reason.phone': 'ફોન નંબર માન્ય નથી: તેમાં 8 થી 15 અંક હોવા જોઈએ.',
  'ops1.kiosk.reason.name': 'નામ બહુ લાંબું છે: વધુમાં વધુ 120 અક્ષર.',
  'ops1.kiosk.reason.lang': 'આ ભાષા પ્લેટફોર્મ પર ઉપલબ્ધ નથી.',
  'ops1.kiosk.reason.rule': 'પ્લેટફોર્મે ફોર્મનું એક ક્ષેત્ર અસ્વીકાર્યું.',
  'ops1.kiosk.reason.forbidden': 'આ સાઇન-ઇન ખાતાં બનાવી શકતું નથી.',
  'ops1.kiosk.reason.create': 'હમણાં ખાતું બની શક્યું નથી.',
  'ops1.kiosk.profile.title': 'નામ અને ભાષા',
  'ops1.kiosk.profile.statement': 'તેનું નામ અને ભાષા એ જ એક ફોર્મ પર નક્કી થાય છે જે ખાતું બનાવે છે. એ પછી તે જાતે, પોતાની ઍપમાં, બદલે છે.',
  'ops1.kiosk.profile.why': 'આ ડેસ્ક કોઈ હાલના ખાતાને બદલતું નથી, અને તેને કોઈ ખાતા વિશે કંઈ બતાવાતું નથી.',
  'ops1.kiosk.land.title': 'જમીન અને પાક',
  'ops1.kiosk.land.statement': 'તે પોતાની જમીન અને પાક જાતે, પોતાની ઍપમાં નોંધે છે. આ ડેસ્ક તેના માટે નોંધતું નથી.',
  'ops1.kiosk.land.why': 'જમીનનો રેકોર્ડ તેની જમીન વિશે તેનું પોતાનું કથન છે, જે તે પોતાના સાઇન-ઇનમાં આપે છે.',
  'ops1.kiosk.kyc.title': 'ઓળખ ચકાસણી (KYC)',
  'ops1.kiosk.kyc.statement': 'તે પોતાની ઓળખ જાતે, પોતાના સાઇન-ઇનમાં, જે ફોન સાથે તેનું આધાર જોડાયેલું છે તેના પર મોકલેલા કોડથી ચકાસે છે. આ ડેસ્ક પર કોઈ આધાર નંબર લખાતો, જોવાતો કે તેનો ફોટો લેવાતો નથી.',
  'ops1.kiosk.kyc.why': 'ડેસ્કને તેના નંબરની ક્યારેય જરૂર નથી. ઓળખપત્રનું ચિત્ર કેવી રીતે રાખવું, અને નંબરનો કેટલો ભાગ બતાવવો, એ વકીલ કહેશે, તેથી અહીં એવું કંઈ લેવાતું નથી.',
  'ops1.kiosk.bank.title': 'બેંક ખાતું',
  'ops1.kiosk.bank.statement': 'તે પોતાનું બેંક ખાતું જાતે, પોતાની ઍપમાં ઉમેરે છે. આ ડેસ્ક તેનો ખાતા નંબર જોતું કે લખતું નથી.',
  'ops1.kiosk.bank.why': 'આ પ્લેટફોર્મ ખાતું ચકાસવા કોઈ પરીક્ષણ ચુકવણી મોકલતું નથી, તેથી અહીં કંઈ પણ ખાતું તેનું છે એવું પુષ્ટિ કરી શકતું નથી.',
  'ops1.kiosk.listing.title': 'પહેલું લિસ્ટિંગ',
  'ops1.kiosk.listing.statement': 'તે પોતાની ઉપજ જાતે, પોતાની ઍપમાં લિસ્ટ કરે છે, અને પ્રકાશિત ફક્ત તે જ કરે છે. આ ડેસ્ક તેના માટે લિસ્ટિંગ કરતું નથી.',
  'ops1.kiosk.listing.why': 'તેના માટે લિસ્ટિંગ કરવા તેની સંમતિ જોઈએ, જેની પુષ્ટિ તે પોતાના ફોન પર કરે. એ હજુ અસ્તિત્વમાં નથી, તેથી કોઈ ડેસ્ક પરથી તેના માટે લિસ્ટિંગ કરતું નથી.',
  'ops1.kiosk.schemes.title': 'યોજનાઓ',
  'ops1.kiosk.schemes.statement': 'તે યોજનાઓ જાતે, પોતાના સાઇન-ઇનમાં ચકાસે છે અને અરજી કરે છે. આ ડેસ્ક તેના માટે અરજી કરતું નથી.',
  'ops1.kiosk.schemes.why': 'અરજીથી એ સાબિત થતું નથી કે કોણે મદદ કરી, તેથી આ ડેસ્ક તેના કોઈ ભાગનો દાવો કરતું નથી.',
  'ops1.kiosk.summary.title': 'તેને શું કહેવું',
  'ops1.kiosk.summary.lead': 'તે જાય તે પહેલાં આ તેને વાંચી સંભળાવો.',
  'ops1.kiosk.summary.did': 'આ ડેસ્કે શું કર્યું: આ નંબર માટે ખાતું બનાવાયું, જો નંબર નવો હતો. અહીં બીજું કંઈ કરાયું નથી.',
  'ops1.kiosk.summary.pay': 'આ ડેસ્ક પર તમારું ખાતું બનાવવાથી મદદ કરનારને કંઈ મળતું નથી, અને તમે કંઈ ચૂકવતા નથી.',
  'ops1.kiosk.summary.helpline': 'તમારી સંસ્થાની હેલ્પલાઇન હજુ પ્રકાશિત થઈ નથી.',
  'ops1.kiosk.summary.undo': 'અહીં કરેલું કંઈ પણ આ ડેસ્ક પરથી પાછું લઈ શકાતું નથી. તે પોતાનું ખાતું અને ડેટા પોતાના સાઇન-ઇનમાં જાતે સંભાળે છે.',
  'ops1.kiosk.earnings.title': 'તમારી કમાણી',
  'ops1.kiosk.earnings.lead': 'તમારી પોતાની કમાણી, દરેક જેમ પ્લેટફોર્મે નોંધી તેમ, સૌથી નવી પહેલાં.',
  'ops1.kiosk.earnings.colWhen': 'નોંધાયું',
  'ops1.kiosk.earnings.colEvent': 'શેના માટે',
  'ops1.kiosk.earnings.colAmount': 'રકમ',
  'ops1.kiosk.earnings.colPaid': 'ચુકવણી',
  'ops1.kiosk.earnings.paidYes': 'ચુકવણી રનમાં',
  'ops1.kiosk.earnings.paidNo': 'હજુ ચૂકવાયું નથી',
  'ops1.kiosk.earnings.empty': 'તમારા માટે હજુ કોઈ કમાણી નોંધાયેલી નથી.',
  'ops1.kiosk.earnings.noTotal': 'કોઈ કુલ બતાવાતો નથી: પ્લેટફોર્મ કોઈ કુલ આપતું નથી, અને આ પાનું કંઈ ઉમેરતું નથી.',
  'ops1.kiosk.earnings.runs': 'તમારી સંસ્થાના ચુકવણી રન અહીં બતાવાતા નથી: રન ફક્ત એ લોકો વાંચી શકે છે જે તેને તૈયાર અને પુષ્ટિ કરે છે.',
