  'ops2.refused.title': 'આ પાનું શું દાવો કરતું નથી',
  'ops2.chain.back': 'પાના પર પાછા જાઓ',
  'ops2.billing.title': 'સંગ્રહ બિલિંગ',
  'ops2.billing.lead': 'આ પ્લેટફોર્મ પર સંગ્રહ ફી શું છે, અને તમે સંચાલન કરો છો તે દરેક ગોદામનો નોંધાયેલ દર. આ પાના પર કોઈ બિલ બનતું નથી.',
  'ops2.billing.statementTitle': 'કોણ ચૂકવે છે, કોને મળત, અને ફી કેવી રીતે નક્કી થાય છે',
  'ops2.billing.payee': 'આજે, જો રિલીઝ ચાલુ હોત, તો ફી જમાકર્તાના વૉલેટમાંથી ગોદામ સંચાલકના પોતાના જ વૉલેટમાં જાત. રિલીઝ અટકેલી છે: એ નક્કી કરવામાં આવ્યું છે કે ફી તમારી સંસ્થાના ખાતામાં જશે, અને તે બને અને જમાકર્તા જાતે તેને પાકું કરી શકે ત્યાં સુધી રિલીઝ પાછી નહીં આવે.',
  'ops2.billing.rule': 'ફી રિલીઝ વખતે એક જ વાર નક્કી થાય છે, તે સમયે નોંધાયેલ દરથી, પૂરા 30-દિવસના ગાળાઓ પ્રમાણે જે ઉપર પૂરા કરાય છે (ઓછામાં ઓછો એક), અને જથ્થો ક્વિન્ટલમાં લેવાય છે.',
