  'ops5.form.cooldownHint': 'એક જ બાબત વિશે કેટલો સમય ચૂપ રહેવું, મિનિટમાં ({min}–{max}). આ જ એક બગડેલા સેન્સરને સો સંદેશા મોકલતાં રોકે છે.',
  'ops5.form.idsHint': 'પ્રતિ લીટી એક આઈડી, કે અલ્પવિરામથી અલગ. વધુમાં વધુ {max}. પુનરાવર્તન દૂર થાય છે — એક ઘટના માટે કોઈને બે વાર જાણ ન થવી જોઈએ.',
  'ops5.done.proposed': 'પ્રસ્તાવિત — બીજી વ્યક્તિની રાહ. બીજી વ્યક્તિ પુષ્ટિ ન કરે ત્યાં સુધી નિયમ બરાબર જેમ છે તેમ જ રહે છે.',
