  'ops5.failure.changeAlreadyOpen': 'આ નિયમ પર પહેલેથી એક ફેરફાર બીજી વ્યક્તિની રાહ જુએ છે. પહેલાં તેની પુષ્ટિ થાય અથવા તે પાછો ખેંચાય.',
