  'ops5.failure.changedSinceProposal': 'પ્રસ્તાવ પછી નિયમ બદલાયો છે, તેથી કંઈ પણ ઉપર લખાયું નથી. પ્રસ્તાવ આપનાર વ્યક્તિ તેને પાછો ખેંચીને ફરી પ્રસ્તાવ આપી શકે છે.',
