  'ops5.refusal.deviceTypeTable': 'નિયમો ડિવાઇસના પ્રકાર પ્રમાણે નથી બનતા, અને કોઈ થોડી મિનિટ રાહ જોતો નથી: નિયમ ત્રણ પ્રકારમાંથી એક હોય છે. ભેજ મપાતો નથી, માટીના પૉડ કોઈ રીડિંગ મોકલતા નથી, અને કોઈ પશુચિકિત્સક ડેસ્કને જણાવાતું નથી.',
  'ops5.refusal.ruleSeverity': 'નિયમ નક્કી નથી કરતો કે તેનો અલર્ટ કેટલો ગંભીર છે: સર્વર દરેક અલર્ટને તેને મળેલી હકીકતોથી આંકે છે.',
  'ops5.refusal.ringsPhone': 'આ પ્લેટફોર્મ બ્રીચ વિશે કોઈને ફોન કરતું નથી: બ્રીચની જાણ ઍપ નોટિફિકેશનથી થાય છે.',
  'ops5.refusal.escalation': 'જો કોઈ અલર્ટ સ્વીકારે નહીં તો આગળ કંઈ થતું નથી: બીજા કોઈને જણાવાતું નથી, અને કોઈએ જવાબ આપ્યો કે નહીં તે નોંધાતું નથી.',
  'ops5.refusal.versions': 'અહીં નિયમનું કોઈ જૂનું સંસ્કરણ ખોલી શકાતું નથી; દરેક ફેરફાર સર્વર પર નોંધાયેલો છે, સંસ્કરણો તરીકે બતાવાતો નથી.',
  'ops5.refusal.platformDefaults': 'કોઈ તૈયાર નિયમો નથી: જે સંસ્થાનો કોઈ નિયમ નથી તેના માટે કોઈ નિયમ ચાલતો નથી.',
  'ops5.refusal.laterWins': 'કોઈ પ્રસ્તાવ બીજાને હટાવતો નથી: નિયમનો વધુમાં વધુ એક પ્રસ્તાવ રાહમાં હોય છે, અને પછી બદલાયેલો નિયમ ક્યારેય ઉપર-લખાતો નથી.',
  'ops5.refusal.anyOpsUser': 'ડેસ્ક પર દરેક જણ પ્રસ્તાવ કરી શકતું નથી: પ્રસ્તાવ અને પુષ્ટિ માટે logistics.manage પરવાનગી જોઈએ, અને કોઈ મંજૂરી આપનાર ભૂમિકા નથી — ફક્ત બીજી વ્યક્તિ.',
  'ops5.refusal.soilPatient': 'માટીનું કોઈ રીડિંગ મળતું નથી, તેથી કોઈ નિયમ માટી પર નજર રાખતો નથી.',
  'ops5.refusal.runNow': 'આ કન્સોલ પરથી નિયમો માંગ પર ચલાવી શકાતા નથી: સર્વર તેમને પોતાના સમયે તપાસે છે.',
  'ops5.refusal.buyerName': 'કોઈ ખરીદનારનું નામ અપાતું નથી અને કોઈ પાક બતાવાતો નથી.',
  'ops5.refusal.cause': 'કોઈ બ્રીચનું કારણ અલગથી નોંધાતું નથી; શું કરાયું તેની નોંધ અહીં બતાવાતી નથી.',
  'ops5.refusal.door': 'કોઈ દરવાજો નોંધાતો નથી: સમયરેખામાં ફક્ત સર્વરે નોંધેલું છે.',
  'ops5.refusal.trailAttached': 'ખરીદનારને કોઈ રીડિંગ ટ્રેલ મોકલાતી નથી: ઑફરમાં ટોચ, બેન્ડ અને મિનિટ હોય છે.',
  'ops5.refusal.bumpNotBreach': 'ખરીદનાર લૉટ સ્વીકારે તેથી બ્રીચ ભૂંસાતો નથી: તે બ્રીચ જ રહે છે.',
  'ops5.refusal.closedByPerson': 'કોઈ વ્યક્તિ બ્રીચ બંધ કરતી નથી: લૉગરનું રીડિંગ બેન્ડની અંદર પાછું આવે ત્યારે સર્વર તેને બંધ કરે છે.',
  'ops5.refusal.tolerance': 'કોઈ છૂટ અપાતી નથી અને કોઈ ક્રમિક નિયમ લાગુ પડતો નથી: બ્રીચ એટલે સળંગ બે સહી કરેલ રીડિંગ બેન્ડની બહાર.',
  'ops5.refusal.causeBlocks': 'બ્રીચને બંધ થવાથી કંઈ રોકતું નથી: પરિણામ ફક્ત રીડિંગ બેન્ડની અંદર પાછા આવ્યા પછી, કારણ સાથે નોંધાય છે.',
  'ops5.refusal.zeroSum': 'અહીં કોઈ પૈસા ફરતા નથી, તેથી કંઈ સરભર કરાતું નથી.',
  'ops5.refusal.onCall': 'કોઈને પેજ કરાતું નથી.',
  'ops5.refusal.auditView': 'દરેક ફેરફાર સર્વર પર નોંધાય છે, પણ આ કન્સોલ પર રેકોર્ડ જોવાની કોઈ સુવિધા નથી.',
  'ops5.refusal.incidentAudit': 'બ્રીચ ફરી વાંચવાથી કંઈ લખાતું નથી.',
  'ops5.refusal.incidentClose': 'અહીં બંધ કરવાનું કંઈ નથી: ફરી પ્રયાસ કરવાથી બ્રીચ ફરી વંચાય છે.',
  // ── PC-56 OPS-5b · W369 and the insights chains (i18n_ops5b.py) ──
  'ops5.ins.title': 'દૂધની માહિતી — આખી સંસ્થા',
  'ops5.ins.signedIn': 'તમે તમારા નામે સાઇન ઇન છો. આ પેજ માટે dairy.manage પરવાનગી જોઈએ. તે ફક્ત સંસ્થાના દૂધના આંકડા વાંચે છે; ફાઇલની નિકાસ અહીંથી માંગવામાં આવે છે અને નોંધાય છે.',
  'ops5.ins.q2': 'આ પેજ આખી સંસ્થાના કુલ આંકડા બતાવે છે. તે કોઈ સભ્યનું નામ લેતું નથી અને કોઈને ક્રમ આપતું નથી.',
  'ops5.ins.q4': 'આ આંકડા આખી સંસ્થાના છે, દરેક કેન્દ્ર પર નોંધાયેલી દૂધની આવકમાંથી. કોઈ એક કેન્દ્રના આંકડા હજી ગણવામાં આવતા નથી.',
